export const computerUseContractCases: Array<{
  name: string;
  input: Parameters<typeof selectComputerUseStatus>;
  expected: ReturnType<typeof selectComputerUseStatus>;
}> = [
  {
    name: "disabled even when ready",
    input: [{ ...computerOn, enabled: false }, computerReady],
    expected: { effective: "off" },
  },
  {
    name: "disabled precedes all eligibility failures",
    input: [{ ...computerOn, enabled: false }, computerIneligible],
    expected: { effective: "off" },
  },
  {
    name: "ready uses node_repl",
    input: [computerOn, computerReady],
    expected: { effective: "active", transport: "node-repl" },
  },
  {
    name: "platform precedes UI/model/runtime",
    input: [computerOn, computerIneligible],
    expected: { effective: "unavailable", reason: "unsupported-platform" },
  },
  {
    name: "UI precedes model/runtime",
    input: [computerOn, { ...computerIneligible, isMac: true }],
    expected: { effective: "unavailable", reason: "no-interactive-ui" },
  },
  {
    name: "model presence precedes image/runtime",
    input: [computerOn, { ...computerIneligible, isMac: true, hasUI: true }],
    expected: { effective: "unavailable", reason: "current-model-missing" },
  },
  {
    name: "image eligibility precedes runtime",
    input: [
      computerOn,
      {
        ...computerIneligible,
        isMac: true,
        hasUI: true,
        currentModelPresent: true,
      },
    ],
    expected: { effective: "unavailable", reason: "model-has-no-image-input" },
  },
  {
    name: "platform alone is ineligible even when everything else is ready",
    input: [computerOn, { ...computerReady, isMac: false }],
    expected: { effective: "unavailable", reason: "unsupported-platform" },
  },
  {
    name: "UI alone is ineligible even when everything else is ready",
    input: [computerOn, { ...computerReady, hasUI: false }],
    expected: { effective: "unavailable", reason: "no-interactive-ui" },
  },
  {
    name: "model absence alone is ineligible even with image/runtime readiness",
    input: [computerOn, { ...computerReady, currentModelPresent: false }],
    expected: { effective: "unavailable", reason: "current-model-missing" },
  },
  {
    name: "image eligibility alone fails even when runtime is ready",
    input: [computerOn, { ...computerReady, modelHasImageInput: false }],
    expected: { effective: "unavailable", reason: "model-has-no-image-input" },
  },
  {
    name: "runtime reason survives eligibility",
    input: [
      computerOn,
      { ...computerReady, runtime: computerIneligible.runtime },
    ],
    expected: {
      effective: "unavailable",
      reason: "missing-chatgpt-desktop-component",
    },
  },
];

